frappe.ui.form.on('Liste prix documents', {
    setup: function(frm) {
        frm.set_query('liste_des_prix', function() {
            return {
                filters: {
                    selling: 1
                }
            };
        });
    },
    liste_des_prix: function(frm) {
        // Ensure the price list is selected
        if (!frm.doc.liste_des_prix) {
            frappe.msgprint('Please select a valid Price List in "liste_des_prix".');
            return;
        }

        // Loop through all items in liste_articles
        (frm.doc.liste_articles || []).forEach((row) => {
            frappe.db.get_value('Item Price', {
                'item_code': row.articles,
                'selling': 1,
                'price_list': frm.doc.liste_des_prix
            }, 'price_list_rate')
            .then(response => {
                if (response && response.message) {
                    let selling_price = response.message.price_list_rate;
                    if (selling_price) {
                        let tva=row.tva
                        let ht=selling_price/(1+tva/100)
                        console.log(tva)

                        frappe.model.set_value(row.doctype, row.name, 'prix_ht',parseFloat(ht.toFixed(3)) );
                        frappe.model.set_value(row.doctype, row.name, 'prix_ttc', parseFloat(selling_price.toFixed(3)));
                    } else {
                        frappe.msgprint(`No price found for item ${row.item_code} in the selected Price List.`);
                    }
                }
            });
        });
    },
    obtenir_articles: function(frm) {
        // 🛠️ Vérification des champs requis
        if (!frm.doc.group_articles || frm.doc.group_articles.length === 0) {
            frappe.msgprint(__('Aucun groupe d\'articles trouvé dans le tableau.'));
            return;
        }

        if (!frm.doc.liste_des_prix) {
            frappe.msgprint(__('Veuillez sélectionner une liste de prix.'));
            return;
        }

        // 🛠️ Extraire les groupes d'articles depuis la table
        let groups = frm.doc.group_articles.map(row => row.goup_articles || 'Non spécifié');
        console.log('✅ Groupes extraits :', groups);
        console.log('✅ Liste des prix :', frm.doc.liste_des_prix);

        // 🛠️ Appel API pour générer la liste des articles
        frappe.call({
            method: 'gener_list_prix',
            args: {
                list_group_item: groups,
                list_prix: frm.doc.liste_des_prix
            },
            callback: function(response) {
                if (response.message) {
                    // Vider la table avant de la remplir
                    console.log('call',response.message);
                    const [item_list, pricing_rules_info] = response.message;
                    frm.set_value('promo_json', pricing_rules_info);
                    frm.refresh_field('promo_json');
                    frm.clear_table('liste_articles');
                    // Ajouter les articles retournés par l'API
                    (item_list || []).forEach(item  => {
                        let new_row = frm.add_child('liste_articles');
                        new_row.articles = item.item_code;
                        new_row.group_articles = item.item_group;
                        new_row.nom_article = item.item_name;
                        new_row.unité = item.stock_uom;
                        new_row.description = item.description;
                        new_row.marque = item.brand;
                        new_row.tva = item.tax_rate;
                        new_row.prix_ht = item.price_ht;
                        new_row.rem=item.remise;
                        new_row.prix_ttc = item.price;
                        new_row.prix_ttc_promo = item.prix_ttc_promo;
                    });

                    frm.refresh_field('liste_articles');
                    frappe.msgprint({
                        title: __('Succès'),
                        indicator: 'green',
                        message: __('La liste des articles a été générée avec succès.')
                    });
                } else {
                    frappe.msgprint({
                        title: __('Erreur'),
                        indicator: 'red',
                        message: __('Aucune donnée reçue de l\'API.')
                    });
                }
            },
            error: function(error) {
                console.error('❌ Erreur API :', error);
                frappe.msgprint({
                    title: __('Erreur'),
                    indicator: 'red',
                    message: __('Une erreur est survenue lors de l\'appel API.')
                });
            }
        });
    }
});
